import{_ as i,o as t,c as a,ag as o}from"./chunks/framework.BwSLX4ak.js";const g=JSON.parse('{"title":"BiliMusicBridge","description":"","frontmatter":{},"headers":[],"relativePath":"en/bilimusicbridge/index.md","filePath":"en/bilimusicbridge/index.md"}'),s={name:"en/bilimusicbridge/index.md"};function r(n,e,d,l,c,u){return t(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="bilimusicbridge" tabindex="-1">BiliMusicBridge <a class="header-anchor" href="#bilimusicbridge" aria-label="Permalink to &quot;BiliMusicBridge&quot;">​</a></h1><p>BiliMusicBridge searches AllMusic&#39;s default music source for Bilibili live chat messages beginning with <code>点歌</code> (“request a song”) and adds the first result to AllMusic&#39;s queue. It supports Bukkit, Folia, BungeeCord, and Velocity. AllMusic and the bridge must run in the same process and on the same platform.</p><h2 id="before-installation" tabindex="-1">Before installation <a class="header-anchor" href="#before-installation" aria-label="Permalink to &quot;Before installation&quot;">​</a></h2><ul><li>AllMusic <strong>4.2.0 or newer</strong> for your platform.</li><li>At least one working source, such as <a href="./../allmusic/qqmusic.html">QQMusic</a> or <a href="./../allmusic/kugou.html">Kugou</a>, with <code>defaultApi</code> configured.</li><li>A matching AllMusic client mod for players to hear music.</li><li>A live room ID and the <a href="https://github.com/hutuyee/BiliMusicBridge/releases" target="_blank" rel="noreferrer">BiliMusicBridge package</a> matching your platform.</li></ul><table tabindex="0"><thead><tr><th>Platform</th><th>Package</th><th>Plugin bytecode requirement</th></tr></thead><tbody><tr><td>Spigot / Paper / Purpur</td><td><code>BiliMusicBridge-Bukkit-*.jar</code></td><td>Java 8+</td></tr><tr><td>Folia</td><td><code>BiliMusicBridge-Folia-*.jar</code></td><td>Java 17+</td></tr><tr><td>BungeeCord / Waterfall</td><td><code>BiliMusicBridge-BungeeCord-*.jar</code></td><td>Java 8+</td></tr><tr><td>Velocity</td><td><code>BiliMusicBridge-Velocity-*.jar</code></td><td>Java 11+</td></tr></tbody></table><p>Also satisfy the Java requirements of your server, proxy, and AllMusic. Folia needs its dedicated package. Install only one platform package per instance.</p><h2 id="first-connection" tabindex="-1">First connection <a class="header-anchor" href="#first-connection" aria-label="Permalink to &quot;First connection&quot;">​</a></h2><ol><li>Install AllMusic and a source first, and confirm your in-game song requests work.</li><li>Put the BiliMusicBridge platform JAR in <code>plugins/</code> and start to generate configuration.</li><li>Set the room ID in the plugin data directory&#39;s <code>config.yml</code>:</li></ol><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">room-id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">123456</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">auto-connect</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">cookie-file</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;cookie.json&quot;</span></span></code></pre></div><ol start="4"><li>Run <code>/bilimusic reload</code>, then <code>/bilimusic status</code>.</li><li>Send <code>点歌 晴天</code> in the live room. By default, at least one eligible player must be online in the game.</li></ol><p>The defaults also recognize <code>点歌晴天</code>, <code>点歌：晴天</code>, <code>点歌: 晴天</code>, and <code>点歌 - 晴天</code>. The plugin uses the default source&#39;s first search result. Viewers do not need a Minecraft account. You can change request prefixes in <code>song-request.prefixes</code>; changing the documentation language does not change these defaults.</p><h2 id="everyday-administration" tabindex="-1">Everyday administration <a class="header-anchor" href="#everyday-administration" aria-label="Permalink to &quot;Everyday administration&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Purpose</th></tr></thead><tbody><tr><td><code>/bilimusic status</code></td><td>Show connection and plugin status</td></tr><tr><td><code>/bilimusic reconnect</code></td><td>Reconnect to the live room</td></tr><tr><td><code>/bilimusic request &lt;song name&gt;</code></td><td>Submit an administrator song request</td></tr><tr><td><code>/bilimusic reload</code></td><td>Reload configuration</td></tr></tbody></table><p>Alias: <code>/bmb</code>. Permission: <code>bilimusic.admin</code>.</p><p>See the <a href="./reference.html">full reference</a> for rate limits, cookies, requester names, queue rules, and configuration examples. See <a href="./troubleshooting.html">Troubleshooting</a> for connection or request failures.</p>`,15)])])}const p=i(s,[["render",r]]);export{g as __pageData,p as default};
